const rows = ref([]);
const loading = ref(false);
const error = ref('');
const searchQuery = ref('');

const slipOpen = ref(false);
const slipInvoiceId = ref(null);
const slipStudentClassId = ref(null);

const unpaidCount = computed(() => rows.value.filter(r => !r.paid).length);
const paidLowCount = computed(() => rows.value.filter(r => r.paid).length);
const filteredRows = computed(() => {
  const q = searchQuery.value.trim();
  if (!q) return rows.value;
  return rows.value.filter(r => r.student_name && r.student_name.includes(q));
});

.tc-search-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}
.tc-search-wrap {
  position: relative;
  display: flex;
  align-items: center;
  min-width: 220px;
  max-width: 320px;
}
.tc-search-icon {
  position: absolute;
  left: 9px;
  font-size: 18px;
  color: var(--text-light);
  pointer-events: none;
}
.tc-search-input {
  width: 100%;
  padding: 7px 32px 7px 34px;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 14px;
  font-family: inherit;
  background: var(--bg);
  color: var(--text);
  transition: border-color 0.15s;
  outline: none;
}
.tc-search-input:focus {
  border-color: var(--primary-light);
  box-shadow: 0 0 0 2px var(--primary-bg);
}
.tc-search-clear {
  position: absolute;
  right: 6px;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--text-light);
  display: flex;
  align-items: center;
  padding: 2px;
}
.tc-search-clear:hover { color: var(--text); }
.tc-search-hint {
  font-size: 13px;
  color: var(--text-light);
}

.tc-table-wrap { overflow-x: auto; }
